import{_ as t,o as a,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const d=JSON.parse('{"title":"里奇·桑图利","description":"","frontmatter":{"title":"里奇·桑图利","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/里奇·桑图利.md","filePath":"04_people/里奇·桑图利.md"}'),s={name:"04_people/里奇·桑图利.md"};function o(i,e,n,_,h,c){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="里奇·桑图利" tabindex="-1">里奇·桑图利 <a class="header-anchor" href="#里奇·桑图利" aria-label="Permalink to &quot;里奇·桑图利&quot;">​</a></h1><ul><li><strong>角色职位</strong>：EJA（NetJets）创始人兼 CEO</li><li><strong>与巴菲特关系</strong>：1998年将 NetJets 出售给伯克希尔·哈撒韦</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>里奇·桑图利（Rich Santulli）是公务航空领域最知名的创业者之一，他于1964年创立了 NetJets，并一手将其打造成为全球最大的公务机分时共享公司。NetJets 的商业模式创新性地推出了&quot;飞机产权分时拥有&quot;概念，客户可以购买飞机的一部分产权，获得在需要时使用公务机的权利，而无需承担整机购买和维护的成本。</p><p>在桑图利的领导下，NetJets 逐步建立起行业领先的运营标准和安全记录，赢得了全球超高净值客户的信赖。公司的客户名单中不乏各国政要、跨国企业 CEO 和富豪阶层，NetJets 几乎成为顶级公务航空服务的代名词。</p><p>1998年，桑图利将 NetJets 出售给伯克希尔·哈撒韦，交易金额约 $7.25 亿美元（后经历调整）。巴菲特一直对公务航空服务情有独钟，认为&quot;飞行的时间是最有价值的资产&quot;。收购 NetJets 与伯克希尔已有的私人飞机业务形成战略协同，也是巴菲特对高端消费服务领域的重要布局。出售后桑图利继续担任 CEO，保持了公司运营的连续性。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1964年</strong>：创立 NetJets，开创公务机分时共享商业模式</li><li><strong>1998年</strong>：将 NetJets 出售给伯克希尔·哈撒韦，成为伯克希尔航空板块的核心资产</li><li><strong>出售后</strong>：继续担任 NetJets CEO，在伯克希尔控股下维持公司全球领先地位</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=里奇·桑图利在2006年股东信中的原话">2006年：完整翻译|/01_letters/2006年/翻译</a></li><li><a href="/search?q=里奇·桑图利在2001年股东信中的原话">2001年：完整翻译|/01_letters/2001年/翻译</a></li><li><a href="/search?q=里奇·桑图利在1999年股东信中的原话">1999年：完整翻译|/01_letters/1999年/翻译</a></li><li><a href="/search?q=里奇·桑图利在2002年股东信中的原话">2002年：完整翻译|/01_letters/2002年/翻译</a></li><li><a href="/search?q=里奇·桑图利在1998年股东信中的原话">1998年：完整翻译|/01_letters/1998年/翻译</a></li></ul>',11)])])}const u=t(s,[["render",o]]);export{d as __pageData,u as default};
